	/**
	 * A randomised oracle over the whole rewrite, run across a fixed set of seeds so a failure is reproducible.
	 *
	 * <p>
	 * The oracle deliberately applies additions and deletions to a set of <em>complete statements</em> and only then
	 * projects to node-and-predicate pairs. Applying them straight to a set of pairs would be a different, easier
	 * problem, and would silently agree with a production bug: deleting one object of a predicate that another
	 * statement still carries on the same node must leave the pair in place, and that is exactly the condition the
	 * incidence check exists to detect. Deriving the expected answer the same way the code does would prove nothing.
	 *
	 * <p>
	 * The identifiers are chosen to sit where sign-handling bugs live. Ordering here is unsigned throughout, so 1, -1,
	 * {@code Long.MIN_VALUE} and {@code Long.MAX_VALUE} are 1, the largest value, the midpoint and the value just below
	 * the midpoint respectively — an implementation that compared them as signed would order every one of them wrongly.
	 */
	@Test
	void aRandomisedOracleAgreesWithEveryRewrite() {
		int rewrites = 0;
		int survivingPredicatesAfterADeletion = 0;
		for (long seed = 1; seed <= 40; seed++) {
			int[] observed = runOracle(seed);
			rewrites += observed[0];
			survivingPredicatesAfterADeletion += observed[1];
		}
		assertThat(rewrites).as("no seed produced a rewrite at all, so this oracle proves nothing").isPositive();
		assertThat(survivingPredicatesAfterADeletion)
				.as("no seed deleted a statement whose predicate survived on the node, which is the one condition"
						+ " the incidence check exists for")
				.isPositive();
	}

	/**
	 * Unsigned-extreme identifiers: 1, 2 and 3 are small, {@code MAX_VALUE} sits just below the midpoint,
	 * {@code MIN_VALUE} is the midpoint, and -2 and -1 are the two largest values of all. Zero is excluded because it
	 * is the "absent row" sentinel.
	 */
	private static final long[] IDS = { 1L, 2L, 3L, Long.MAX_VALUE - 1, Long.MAX_VALUE, Long.MIN_VALUE,
			Long.MIN_VALUE + 1, -2L, -1L };
	/** Only the outgoing planes, matching the mask the fixtures are built with. */
	private static final int[] PLANES = { 0, 2 };

	private int[] runOracle(long seed) {
		Random random = new Random(seed);
		String where = "seed=" + seed;

		// A statement here is (plane, node, predicate, object). Objects exist only so that a predicate can survive the
		// deletion of one of its statements, which is the whole point of the incidence check.
		Set<List<Long>> statements = new LinkedHashSet<>();
		int initial = 8 + random.nextInt(24);
		for (int i = 0; i < initial; i++) {
			statements.add(statement(random));
		}
		NavigableMap<List<Long>, NavigableSet<Long>> before = project(statements);
		if (before.isEmpty()) {
			return new int[] { 0, 0 };
		}

		Set<List<Long>> additions = new LinkedHashSet<>();
		for (int i = 0, additionCount = random.nextInt(8); i < additionCount; i++) {
			List<Long> candidate = statement(random);
			if (!statements.contains(candidate)) {
				additions.add(candidate);
			}
		}
		List<List<Long>> existing = new ArrayList<>(statements);
		Set<List<Long>> deletions = new LinkedHashSet<>();
		for (int i = 0, deletionCount = random.nextInt(8); i < deletionCount && !existing.isEmpty(); i++) {
			deletions.add(existing.get(random.nextInt(existing.size())));
		}

		Set<List<Long>> after = new LinkedHashSet<>(statements);
		after.addAll(additions);
		after.removeAll(deletions);
		NavigableMap<List<Long>, NavigableSet<Long>> expected = project(after);
		// How many deletions removed a statement whose predicate is still present on the node afterwards. A pair-level
		// oracle would wrongly drop those, which is exactly why this one works on statements.
		int survivors = 0;
		for (List<Long> deleted : deletions) {
			NavigableSet<Long> row = expected.get(List.of(deleted.get(0), deleted.get(1)));
			if (row != null && row.contains(deleted.get(2))) {
				survivors++;
			}
		}

		// The changed-row feed carries one entry per touched (node, plane, predicate), with the tombstone flag telling
		// the truth the store learned by counting incidences: is anything left under this predicate on this node?
		TreeSet<List<Long>> touched = new TreeSet<>(CHANGED_ROW_ORDER);
		for (List<Long> changed : concat(additions, deletions)) {
			touched.add(List.of(changed.get(1), changed.get(0), changed.get(2)));
		}
		long[] keys = new long[touched.size()];
		int[] planes = new int[touched.size()];
		long[] predicates = new long[touched.size()];
		boolean[] tombstones = new boolean[touched.size()];
		int index = 0;
		for (List<Long> entry : touched) {
			keys[index] = entry.get(0);
			planes[index] = Math.toIntExact(entry.get(1));
			predicates[index] = entry.get(2);
			NavigableSet<Long> row = expected.get(List.of(entry.get(1), entry.get(0)));
			tombstones[index] = row == null || !row.contains(entry.get(2));
			index++;
		}

		try (LmdbNodePredicateIndex old = projection(rowsOf(before))) {
			LmdbNodePredicateUpdates updates = new LmdbNodePredicateUpdates(
					new ChangedRows(keys, planes, predicates, tombstones), old);
			if (updates.size() == 0) {
				assertThat(expected).as("%s: nothing to rewrite, so the projection must be unchanged", where)
						.isEqualTo(before);
				return new int[] { 0, survivors };
			}
			ImmutablePagedQuadCsfIndex.RewriteResult rewrite = old.rewrite(updates,
					(nativeBytes, modeledJavaBytes) -> () -> {
					});
			try (LmdbNodePredicateIndex rewritten = LmdbNodePredicateIndex.wrap(rewrite.index(), old.planeMask())) {
				for (int plane : PLANES) {
					for (long node : IDS) {
						NavigableSet<Long> row = expected.get(List.of((long) plane, node));
						long[] want = row == null ? new long[0]
								: row.stream().mapToLong(Long::longValue).toArray();
						assertThat(row(rewritten, plane, node))
								.as("%s: plane=%d node=%s", where, plane, Long.toUnsignedString(node))
								.containsExactly(want);
					}
				}
				// The pinned old snapshot must be untouched by the rewrite, because two live bases share pages.
				for (int plane : PLANES) {
					for (long node : IDS) {
						NavigableSet<Long> row = before.get(List.of((long) plane, node));
						long[] want = row == null ? new long[0]
								: row.stream().mapToLong(Long::longValue).toArray();
						assertThat(row(old, plane, node))
								.as("%s: the old snapshot changed at plane=%d node=%s", where, plane,
										Long.toUnsignedString(node))
								.containsExactly(want);
					}
				}
			}
		}
		return new int[] { 1, survivors };
	}

	private static List<List<Long>> concat(Set<List<Long>> first, Set<List<Long>> second) {
		List<List<Long>> all = new ArrayList<>(first);
		all.addAll(second);
		return all;
	}

	/** One random statement as (plane, node, predicate, object). */
	private static List<Long> statement(Random random) {
		return List.of((long) PLANES[random.nextInt(PLANES.length)], IDS[random.nextInt(IDS.length)],
				IDS[random.nextInt(IDS.length)], (long) random.nextInt(3));
	}

	/** Projects a statement set to (plane, node) → sorted distinct predicates, which is what the sidecar stores. */
	private static NavigableMap<List<Long>, NavigableSet<Long>> project(
			Set<List<Long>> statements) {
		NavigableMap<List<Long>, NavigableSet<Long>> rows = new TreeMap<>(ROW_KEY_ORDER);
		for (List<Long> statement : statements) {
			rows.computeIfAbsent(List.of(statement.get(0), statement.get(1)),
					key -> new TreeSet<>(Long::compareUnsigned)).add(statement.get(2));
		}
		return rows;
	}

	/** Builder input: plane-major, then key ascending unsigned, which is the order the CSF builder requires. */
	private static Row[] rowsOf(NavigableMap<List<Long>, NavigableSet<Long>> rows) {
		List<Row> result = new ArrayList<>();
		rows.forEach((key, predicates) -> result.add(new Row(Math.toIntExact(key.get(0)), key.get(1),
				predicates.stream().mapToLong(Long::longValue).toArray())));
		return result.toArray(new Row[0]);
	}

	/** (plane, key): plane ascending, then key ascending unsigned. */
	private static final Comparator<List<Long>> ROW_KEY_ORDER = Comparator
			.<List<Long>>comparingLong(key -> key.get(0))
			.thenComparing(key -> key.get(1), Long::compareUnsigned);

	/** (key, plane, predicate): the order the changed-row feed must arrive in. */
	private static final Comparator<List<Long>> CHANGED_ROW_ORDER = Comparator
			.<List<Long>, Long>comparing(entry -> entry.get(0), Long::compareUnsigned)
			.thenComparingLong(entry -> entry.get(1))
			.thenComparing(entry -> entry.get(2), Long::compareUnsigned);

	private static String[] updateCoordinates(LmdbNodePredicateUpdates updates) {
		String[] result = new String[updates.size()];
		for (int i = 0; i < result.length; i++) {
			result[i] = updates.partitionAt(i) + "/" + updates.rowAt(i);
		}
		return result;
	}

	private static long[] copy(LmdbNodePredicateUpdates updates, int index) {
		long[] result = new long[Math.toIntExact(updates.pairCountAt(index))];
		assertThat(updates.copyPairsAt(index, 0, result.length, result, 0, null, 0)).isEqualTo(result.length);
		return result;
	}

	private static long[] row(LmdbNodePredicateIndex index, int plane, long subject) {
		long reference = index.findLocalReference(plane, subject, new ImmutablePagedQuadCsfIndex.LookupCursor());
		if (reference == 0) {
			return new long[0];
		}
		ImmutablePagedQuadCsfIndex.RowCursor cursor = new ImmutablePagedQuadCsfIndex.RowCursor();
		index.resolve(reference, cursor);
		long[] result = new long[Math.toIntExact(cursor.edgeCount())];
		assertThat(cursor.copy(0, result.length, result, 0, null, 0)).isEqualTo(result.length);
		return result;
	}

	private static LmdbNodePredicateIndex projection(Row... rows) {
		ImmutablePagedQuadCsfIndex.BuildPlan plan;
		try (ImmutablePagedQuadCsfIndex.Builder builder = ImmutablePagedQuadCsfIndex.sizingBuilder(1)) {
			emit(builder, rows);
			plan = builder.finishPlan();
		}
		try (ImmutablePagedQuadCsfIndex.Builder builder = ImmutablePagedQuadCsfIndex.materializingBuilder(plan)) {
			emit(builder, rows);
			return LmdbNodePredicateIndex.wrap(builder.finishIndex(), LmdbNodePredicateOptions.OUTGOING.planeMask());
		}
	}

	private static void emit(ImmutablePagedQuadCsfIndex.Builder builder, Row[] rows) {
		for (Row row : rows) {
			builder.beginRow(0, row.plane, row.subject);
			for (long predicate : row.predicates) {
				builder.pair(predicate, 0);
			}
			builder.endRow();
		}
	}

	private record Row(int plane, long subject, long... predicates) {
	}

	private record ChangedRows(long[] keys, int[] planes, long[] predicates, boolean[] tombstones)
			implements LmdbNodePredicateUpdates.ChangedRows {
		private ChangedRows {
			if (planes.length != keys.length || predicates.length != keys.length || tombstones.length != keys.length) {
				throw new IllegalArgumentException("changed-row columns must have equal length");
			}
		}

		@Override
		public int size() {
			return keys.length;
		}

		@Override
		public long keyAt(int index) {
			return keys[index];
		}

		@Override
		public int planeAt(int index) {
			return planes[index];
		}

		@Override
		public long predicateAt(int index) {
			return predicates[index];
		}

		@Override
		public boolean tombstoneAt(int index) {
			return tombstones[index];
		}
	}
